import{_ as t,o,c as i,a5 as l}from"./chunks/framework.CsGesDJn.js";const f=JSON.parse('{"title":"Sequence Flow — Update Client Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/profile/3-3-4-update-client-profile/sequence-flow.md","filePath":"feature/profile/3-3-4-update-client-profile/sequence-flow.md"}'),r={name:"feature/profile/3-3-4-update-client-profile/sequence-flow.md"};function a(n,e,d,s,c,h){return o(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="sequence-flow-—-update-client-profile" tabindex="-1">Sequence Flow — Update Client Profile <a class="header-anchor" href="#sequence-flow-—-update-client-profile" aria-label="Permalink to &quot;Sequence Flow — Update Client Profile&quot;">​</a></h1><p>&gt; Supplements <code>spec.md</code> (FR 3.3.4). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly — it does not restate business rules (see spec.md for those). &gt; &gt; Updated: 2026-10-02. ClientProfile reworked — owned by the User, independent of any Agency.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>User</strong> — any signed-in user, creating or editing a Client Profile they own.</li><li><strong>Client</strong> — the create/edit form on &quot;My Brand Profiles&quot; (FR 3.3.3).</li><li><strong>System</strong> — the application services.</li><li><strong>Database</strong> — PostgreSQL (<code>client_profiles</code>, <code>workspace_members</code>).</li></ul><h2 id="reminder-—-owned-by-the-user-never-scoped-to-an-agency" tabindex="-1">Reminder — owned by the User, never scoped to an Agency <a class="header-anchor" href="#reminder-—-owned-by-the-user-never-scoped-to-an-agency" aria-label="Permalink to &quot;Reminder — owned by the User, never scoped to an Agency&quot;">​</a></h2><p>Unlike the reverted 2026-09-21 model, there is no &quot;(user, agency) pair&quot; — a single profile row can be linked to workspaces of any number of Agencies. Editing it changes that one row; the change is visible wherever it is linked.</p><hr><h2 id="flow-a-—-create-a-new-client-profile" tabindex="-1">Flow A — Create a new Client Profile <a class="header-anchor" href="#flow-a-—-create-a-new-client-profile" aria-label="Permalink to &quot;Flow A — Create a new Client Profile&quot;">​</a></h2><ol><li>User → Client: fills the form — display name (required), company, phone, note, logo, website, industry, location, description, social links, brand fields — and clicks Save.</li><li>Client → System: <code>POST /api/v1/client-profile</code> with the full field set. <ul><li>An empty or blank display name is rejected → <code>400 VALIDATION_ERROR</code>.</li><li>The request carries no email field — the owner&#39;s own email cannot be submitted through this action.</li></ul></li><li>System: a. Resolves the caller&#39;s identity from the access token. b. Builds a new <code>ClientProfile</code> with <code>userId = caller</code>, no Agency reference of any kind.</li><li>System → Database: inserts the record.</li><li>System → Client: returns the complete Client Profile.</li><li>Client: shows a success confirmation and adds the new card to the list.</li></ol><h2 id="flow-b-—-update-an-existing-client-profile" tabindex="-1">Flow B — Update an existing Client Profile <a class="header-anchor" href="#flow-b-—-update-an-existing-client-profile" aria-label="Permalink to &quot;Flow B — Update an existing Client Profile&quot;">​</a></h2><ol><li>User → Client: edits an existing card&#39;s form and clicks Save.</li><li>Client → System: <code>PUT /api/v1/client-profile/{profileId}</code> with the full field set.</li><li>System: a. System → Database: <code>findById(profileId)</code> — no record → <code>404 CLIENT_PROFILE_NOT_FOUND</code>. b. Checks <code>profile.userId == caller.id</code> — mismatch → <code>403 CLIENT_PROFILE_NOT_OWNED</code>. c. Writes the complete field set over the record (full overwrite) and stamps the update time.</li><li>System → Database: saves the record.</li><li>System → Client: returns the complete Client Profile.</li><li>Client: shows a success confirmation and refreshes the list. Because the profile is never Agency-scoped, the new values are visible wherever it is linked (every workspace of every Agency) immediately — no manual synchronization, no &quot;per-Agency copy&quot; to keep in sync.</li></ol><h2 id="flow-c-—-delete-a-client-profile" tabindex="-1">Flow C — Delete a Client Profile <a class="header-anchor" href="#flow-c-—-delete-a-client-profile" aria-label="Permalink to &quot;Flow C — Delete a Client Profile&quot;">​</a></h2><ol><li>User → Client: clicks Delete on a card.</li><li>Client → System: <code>DELETE /api/v1/client-profile/{profileId}</code>.</li><li>System: a. Checks ownership as in Flow B step b. b. System → Database: <code>workspaceMemberRepository.findByClientProfileIdInAndIsActiveTrue([profileId])</code> — not empty → <code>409 CLIENT_PROFILE_IN_USE</code>.</li><li>System → Database: deletes the record.</li><li>System → Client: confirms deletion; the card is removed from the list.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>ErrorCode</th></tr></thead><tbody><tr><td>Create/Update (Flow A/B)</td><td>Display name empty or blank</td><td>400</td><td><code>VALIDATION_ERROR</code></td></tr><tr><td>Update/Delete (Flow B/C)</td><td>Profile not found</td><td>404</td><td><code>CLIENT_PROFILE_NOT_FOUND</code></td></tr><tr><td>Update/Delete (Flow B/C)</td><td>Profile belongs to a different user</td><td>403</td><td><code>CLIENT_PROFILE_NOT_OWNED</code></td></tr><tr><td>Delete (Flow C)</td><td>Profile linked to an active workspace membership</td><td>409</td><td><code>CLIENT_PROFILE_IN_USE</code></td></tr><tr><td>Any</td><td>Missing, expired, or invalid token</td><td>401</td><td><code>UNAUTHORIZED</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>There is no upsert anymore — create (<code>POST</code>) and update (<code>PUT /{profileId}</code>) are distinct requests. The 2026-09-21 upsert-by-<code>(userId, agencyId)</code> behaviour was reverted on 2026-10-02 along with the <code>agency_id</code> column.</li><li>There is no dedicated error code to block the owner&#39;s own email field — the request simply has no place to carry it, so it can never be sent.</li></ul>',18)])])}const u=t(r,[["render",a]]);export{f as __pageData,u as default};
